<template>
  <div class="poster-wordmark" :class="{ 'poster-wordmark--immediate': immediate }" aria-hidden="true">
    <svg v-for="plate in plates" :key="plate.name"
      class="poster-wordmark__plate" :class="'poster-wordmark__plate--' + plate.name"
      :viewBox="'0 0 ' + plate.width + ' ' + plate.height" preserveAspectRatio="none">
      <defs>
        <pattern :id="instance + '-ink-' + plate.name" patternUnits="userSpaceOnUse"
          patternContentUnits="userSpaceOnUse" :width="plate.width" :height="plate.height">
          <image :href="plate.ink" :width="plate.width" :height="plate.height" preserveAspectRatio="none" />
        </pattern>
      </defs>
      <g :fill="'url(#' + instance + '-ink-' + plate.name + ')'" fill-rule="evenodd">
        <g class="poster-wordmark__corridor"><path :d="plate.corridor" /></g>
        <g v-for="(outline, i) in plate.letters" :key="i" class="poster-wordmark__glyph"
          :data-letter="'RUSH'[i]" :style="{ '--ink-delay': (400 + i * 52) + 'ms' }">
          <path :d="outline" />
        </g>
      </g>
    </svg>
  </div>
</template>

<style>
.poster-wordmark {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
}
.poster-wordmark__plate {
  display: block;
  width: 100%;
  height: 100%;
}
.poster-wordmark__plate--portrait { display: none; }
@media (orientation: portrait) {
  .poster-wordmark__plate--wide { display: none; }
  .poster-wordmark__plate--portrait { display: block; }
}
.poster-wordmark__corridor, .poster-wordmark__glyph {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center bottom;
}
.poster-art--ready .poster-wordmark:not(.poster-wordmark--immediate) .poster-wordmark__corridor {
  animation: poster-wordmark-small 500ms cubic-bezier(.22,.68,.29,1) 280ms both;
}
.poster-art--ready .poster-wordmark:not(.poster-wordmark--immediate) .poster-wordmark__glyph {
  animation: poster-wordmark-letter 580ms cubic-bezier(.23,.71,.23,1) var(--ink-delay) both;
}
.poster-wordmark--immediate :is(.poster-wordmark__corridor, .poster-wordmark__glyph) { opacity: 1; }
@keyframes poster-wordmark-small {
  from { opacity: 0; transform: translateY(5%); }
  to { opacity: 1; transform: none; }
}
@keyframes poster-wordmark-letter {
  from { opacity: 0; clip-path: inset(100% -3% -2%) fill-box; transform: translateY(2%) skewX(-.55deg); }
  47% { opacity: .94; }
  to { opacity: 1; clip-path: inset(-2%) fill-box; transform: none; }
}
@media (prefers-reduced-motion: reduce) {
  .poster-wordmark :is(.poster-wordmark__corridor, .poster-wordmark__glyph),
  .poster-art--ready .poster-wordmark:not(.poster-wordmark--immediate) :is(.poster-wordmark__corridor, .poster-wordmark__glyph) {
    animation: none;
    opacity: 1;
  }
}
</style>
